def build(*,interpolation=False):
    """Preserve the exact matching branch; use a finite cut only when needed."""
    core=finite(interpolation=interpolation);name='Prochitecture Streets / Original seam profile reconciliation v1'
    if interpolation:name+=' / Exact and mixed frames v2'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for s in core.interface.items_tree:
        if s.item_type=='SOCKET':g.socket(s.name,s.socket_type,s.in_out,default=getattr(s,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    matching=g.node('GeometryNodeGroup');matching.node_tree=seam.build(interpolation=interpolation)
    transition=g.node('GeometryNodeGroup');transition.node_tree=core
    for node in (matching,transition):
        for s in node.node_tree.interface.items_tree:
            if s.item_type=='SOCKET' and s.in_out=='INPUT':g.bind(inp.outputs[s.name],node.inputs[s.name])
    # Matching validity includes all ownership/path checks. If it rejects,
    # the finite provider independently validates the same original inputs.
    for s in core.interface.items_tree:
        if s.item_type=='SOCKET' and s.in_out=='OUTPUT':
            kind='BOOLEAN' if s.socket_type=='NodeSocketBool' else 'GEOMETRY'
            g.bind(c.choose(g,matching.outputs['Valid'],matching.outputs[s.name],transition.outputs[s.name],kind),out.inputs[s.name])
    return g.g
